from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = dict(jumps)
    destination = list(range(n + 1))

    for cell in range(1, n):
        pos = cell
        while pos in jump:
            pos = jump[pos]
        destination[cell] = pos

    transitions = [{} for _ in range(n + 1)]
    reverse = [[] for _ in range(n + 1)]

    for pos in range(n):
        counts = transitions[pos]
        for roll in range(1, m + 1):
            landing = pos + roll
            if landing > n:
                landing = 2 * n - landing
            target = destination[landing]
            counts[target] = counts.get(target, 0) + 1

        for target in counts:
            reverse[target].append(pos)

    reachable = {0}
    stack = [0]
    while stack:
        pos = stack.pop()
        for target in transitions[pos]:
            if target not in reachable:
                reachable.add(target)
                stack.append(target)

    can_finish = {n}
    stack = [n]
    while stack:
        target = stack.pop()
        for pos in reverse[target]:
            if pos not in can_finish:
                can_finish.add(pos)
                stack.append(pos)

    if not reachable.issubset(can_finish):
        return None

    states = sorted(reachable - {n})
    index = {pos: i for i, pos in enumerate(states)}
    size = len(states)

    # Multiply each expectation equation by m to obtain integer coefficients.
    matrix = [[0] * (size + 1) for _ in range(size)]
    for i, pos in enumerate(states):
        matrix[i][i] = m
        matrix[i][size] = m
        for target, count in transitions[pos].items():
            if target != n:
                matrix[i][index[target]] -= count

    # Bareiss elimination keeps all intermediate coefficients integral.
    # Almost-sure absorption makes every leading principal minor positive.
    previous_pivot = 1
    for k in range(size - 1):
        pivot_row = matrix[k]
        pivot = pivot_row[k]

        for i in range(k + 1, size):
            row = matrix[i]
            factor = row[k]
            for j in range(k + 1, size + 1):
                row[j] = (
                    pivot * row[j] - factor * pivot_row[j]
                ) // previous_pivot
            row[k] = 0

        previous_pivot = pivot

    expectations = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * expectations[j]
        expectations[i] = value / matrix[i][i]

    answer = expectations[index[0]]
    return [answer.numerator, answer.denominator]
